# The shipped datasets, and the promise their generator makes.
#
# Shipped data must be reproducible from its stated origin. These datasets are
# generated by code this package contains, and this file is what keeps the two
# in step: change the generator without regenerating, or
# regenerate without meaning to, and these fail.

test_that("the three datasets are present and are netis_data", {
  for (d in list(demo_influence, demo_influence_groups, demo_selection)) {
    expect_s3_class(d, "netis_data")
  }
})

test_that("each dataset has the structure its documentation claims", {
  # A format section that drifts from the object is a small lie in a place
  # readers trust, so the claims are asserted rather than maintained by hand.
  inf <- netis_nodes(demo_influence)
  expect_true(all(c("group", "node", "wave", "y", "x") %in% names(inf)))
  expect_equal(length(unique(inf$node)), 30L)
  expect_equal(sort(unique(inf$wave)), c(1, 2))
  expect_equal(length(unique(inf$group)), 1L)

  grp <- netis_nodes(demo_influence_groups)
  expect_true(all(c("y", "x") %in% names(grp)))
  expect_equal(length(unique(grp$group)), 4L)
  # UNEQUAL ON PURPOSE. With equal group sizes the three icc2() n_j
  # conventions coincide, so a balanced dataset cannot show a reader that the
  # choice exists, let alone what it changes.
  sizes <- table(unique(grp[c("group", "node")])$group)
  expect_gt(length(unique(as.integer(sizes))), 1L)
  expect_equal(sum(sizes), 42L)

  sel <- netis_ties(demo_selection)
  expect_true(all(c("group", "source", "target", "wave", "tie") %in% names(sel)))
  # Every ordered pair at every wave: 20 * 19 = 380 per wave.
  expect_equal(nrow(sel), 760L)
  expect_equal(as.integer(table(sel$wave)), c(380L, 380L))
  expect_true(all(sel$tie %in% c(0, 1)))
})

test_that("demo_selection declares that its zeros are measured", {
  # THE DISTINCTION rnetis REFUSES TO INFER. A complete dyadic table and a
  # sparse edge list look alike; in the first a zero is an observed non-tie,
  # in the second it is an absent row. This dataset is the first, and it says
  # so rather than leaving a fit to guess.
  desc <- netis_schema(demo_selection)$tie_descriptors$tie
  expect_identical(desc$zero_meaning, "measured_zero")
})

test_that("the generated datasets carry the parameters that produced them", {
  # WHY GENERATED DATA RATHER THAN A HAND-TYPED TABLE. An example can fit a
  # model to these and compare the estimate against the value that generated
  # it -- a demonstration that the function works, not only that it runs.
  ti <- attr(demo_influence, "truth")
  expect_false(is.null(ti))
  expect_equal(ti$gamma, 0.4)
  expect_equal(ti$beta, 0.3)

  ts <- attr(demo_selection, "truth")
  expect_false(is.null(ts))
  expect_equal(ts$prior_tie, 1.6)
  expect_equal(ts$snd_tenure, 0.5)
})

test_that("demo_influence recovers its own generating parameters", {
  # The claim the `truth` attribute exists to support, checked once here so
  # that an example relying on it is relying on something tested.
  fit <- fit_influence(y ~ ar() + exposure(y, via = tie, normalize = "row"),
                       data = demo_influence)
  truth <- attr(demo_influence, "truth")
  est <- coef(fit)

  # Wide tolerances: 30 actors and one transition is a small sample, and the
  # point is that the estimates are in the right place rather than that this
  # fixture is precise. A route that recovered nothing would miss by far more.
  expect_equal(unname(est[["y_lag1"]]), truth$gamma, tolerance = 0.35)
  expect_equal(unname(est[["ex_y_tie"]]), truth$beta, tolerance = 0.35)
})

test_that("demo_influence's covariate is independent of its outcome process", {
  # `x` was added for examples that want exposure to an alter ATTRIBUTE rather
  # than to the outcome. Its independence is the point: an example using the
  # outcome for both would confound the illustration with a real endogeneity,
  # which is a different lesson than the one the example is teaching.
  n <- netis_nodes(demo_influence)
  n <- n[n$wave == 2, ]
  expect_lt(abs(stats::cor(n$x, n$y)), 0.45)
})

test_that("demo_influence_groups records its network at wave 1 only", {
  # A tie table covering one wave of a two-wave study describes that wave. It
  # is not fanned out to wave 2, where the network was not observed.
  ties <- netis_ties(demo_influence_groups)
  expect_identical(sort(unique(as.numeric(ties$wave))), 1)
  a1 <- netis_adjacency(demo_influence_groups, "tie", wave = 1)[["a"]]
  expect_warning(
    a2 <- netis_adjacency(demo_influence_groups, "tie", wave = 2)[["a"]],
    "group a wave 2"
  )
  expect_identical(a1["a01", "a02"], 1)   # the ring a01 -> a02
  expect_identical(sum(a2), 0)
})
